export function errorMessage(error: unknown, labels: BlogsLabels) {
  const code = error && typeof error === "object" && "code" in error ? String(error.code) : "";
  return [
    "HISTORY_CONFIRMATION_REQUIRED",
    "AUTHOR_REQUIRED",
    "INVALID",
    "CONFLICT",
    "FORBIDDEN",
    "NOT_FOUND",
    "IN_USE",
    "STORAGE",
    "STORAGE_NOT_CONFIGURED",
  ].includes(code)
    ? labels[code as "INVALID"]
    : labels.error;
}
export function Feedback({ message, error = false }: { message?: string; error?: boolean }) {
  return message ? (
    <p
      role={error ? "alert" : "status"}
      className={cn("text-sm", error ? "text-destructive" : "text-muted-foreground")}
    >
      {message}
    </p>
  ) : null;
}
export function useBlogAction(labels: BlogsLabels) {
  const notify = useActionToast();
  const { add } = Toast.useToastManager();
  const lock = useRef(false);
  const request = useRef<{ key: string; id: string } | null>(null);
  const [pending, setPending] = useState(false),
    [feedback, setFeedback] = useState<{ message: string; error?: boolean }>();
  async function run<T>(
    key: string,
    action: (requestId: string) => Promise<T>,
    success?: string,
  ): Promise<T | undefined> {
    if (lock.current) return;
    lock.current = true;
    setPending(true);
    setFeedback(undefined);
    if (request.current?.key !== key) request.current = { key, id: crypto.randomUUID() };
    try {
      const result = await action(request.current.id);
      request.current = null;
      if (success) notify(success);
      return result;
    } catch (error) {
      const message = errorMessage(error, labels);
      if (
        error &&
        typeof error === "object" &&
        "code" in error &&
        error.code === "STORAGE_NOT_CONFIGURED"
      ) {
        add({ title: message, type: "error" });
      } else {
        setFeedback({ message, error: true });
      }
      return undefined;
    } finally {
      lock.current = false;
      setPending(false);
    }
  }
  return { pending, feedback, run };
}
export function ConfirmDelete({
  labels,
  title,
  description,
  onDelete,
  disabled = false,
  label,
  onClose,
  finalFocus,
}: {
  labels: BlogsLabels;
  title: string;
  description: string;
  onDelete: (requestId: string) => Promise<void>;
  disabled?: boolean;
  label: string;
  onClose?: () => void;
  finalFocus?: Dialog.Popup.Props["finalFocus"];
}) {
  const [open, setOpen] = useState(!!onClose);
  const action = useBlogAction(labels);
  return (
    <Dialog.Root
      open={open}
      onOpenChange={(next) => {
        if (!action.pending) {
          setOpen(next);
          if (!next) onClose?.();
        }
      }}
    >
      {!onClose && (
        <IconTooltip label={label}>
          <Dialog.Trigger
            className={cn(
              iconButtonClass,
              "bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30",
            )}
            aria-label={label}
            disabled={disabled}
          >
            <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
          </Dialog.Trigger>
        </IconTooltip>
      )}
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
        <Dialog.Popup
          finalFocus={finalFocus}
          className={cn(
            cardClass,
            "fixed top-1/2 left-1/2 z-50 w-[calc(100%-2rem)] max-w-md -translate-x-1/2 -translate-y-1/2 space-y-5 shadow-xl",
          )}
        >
          <Dialog.Title className="text-lg font-semibold">{title}</Dialog.Title>
          <Dialog.Description className="text-sm text-muted-foreground">
            {description}
          </Dialog.Description>
          <div className="min-h-10">
            <Feedback {...action.feedback} />
          </div>
          <div className="flex flex-wrap justify-end gap-2">
            <Dialog.Close className={outlineButtonClass} disabled={action.pending}>
              {labels.cancel}
            </Dialog.Close>
            <button
              className={cn(
                primaryClass,
                "bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30",
              )}
              disabled={disabled || action.pending}
              onClick={() =>
                void action.run("delete", async (requestId) => {
                  await onDelete(requestId);
                  setOpen(false);
                  onClose?.();
                  return true;
                })
              }
            >
              {action.pending ? labels.pending : labels.confirmDelete}
            </button>
          </div>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}
export function Pagination({
  page,
  total,
  pageSize,
  onPageChange,
  labels,
  disabled = false,
}: {
  page: number;
  total: number;
  pageSize: number;
  onPageChange: (page: number) => void;
  labels: BlogsLabels;
  disabled?: boolean;
}) {
  const pages = Math.max(1, Math.ceil(total / pageSize));
  return (
    <TablePagination
      summary={`${total} ${labels.totalItems}`}
      page={page}
      pageCount={pages}
      label={labels.pageLabel(page, pages)}
      previousLabel={labels.previous}
      nextLabel={labels.next}
      previousDisabled={page <= 1}
      nextDisabled={page >= pages}
      disabled={disabled}
      onPrevious={() => onPageChange(page - 1)}
      onNext={() => onPageChange(page + 1)}
    />
  );
}

